use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, Write};
use std::process::ExitCode;

const TOP: usize = 10;

fn is_word_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric()
}

fn main() -> ExitCode {
    let Some(path) = env::args_os().nth(1) else {
        eprintln!("usage: word_frequency <file>");
        return ExitCode::FAILURE;
    };

    let bytes = match fs::read(&path) {
        Ok(bytes) => bytes,
        Err(err) => {
            eprintln!("word_frequency: cannot read {}: {err}", path.to_string_lossy());
            return ExitCode::FAILURE;
        }
    };

    let mut counts: HashMap<Vec<u8>, u64> = HashMap::new();
    for word in bytes.split(|&b| !is_word_byte(b)) {
        if word.is_empty() {
            continue;
        }
        let lower = word.to_ascii_lowercase();
        *counts.entry(lower).or_insert(0) += 1;
    }

    let mut entries: Vec<(Vec<u8>, u64)> = counts.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));

    let stdout = io::stdout();
    let mut out = stdout.lock();
    for (word, count) in entries.iter().take(TOP) {
        let result = out
            .write_all(word)
            .and_then(|()| write!(out, " {count}\n"));
        if let Err(err) = result {
            eprintln!("word_frequency: cannot write output: {err}");
            return ExitCode::FAILURE;
        }
    }
    if let Err(err) = out.flush() {
        eprintln!("word_frequency: cannot write output: {err}");
        return ExitCode::FAILURE;
    }

    ExitCode::SUCCESS
}

